  --rr-color-grey-1: #F8F8F8;
  --rr-color-grey-2: #2D343E;
  --rr-color-grey-light: #F2F3F4;
  --rr-color-border-1: #1E2228;
  --rr-color-border-light: #E4E4E4;
}

