/* Site Preloader */
#preloader {
  position: fixed;
  width: 100%;
  height: 100%;
  left: 0;
  top: 0;
  background-color: #02050A;
  z-index: 999;
  display: flex;
  align-items: center;
  justify-content: center;
}

.loading {
  position: relative;
  display: inline-block;
  font-size: clamp(36px, 7vw, 68px);
  font-family: var(--rr-ff-heading);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  text-transform: none;
  white-space: nowrap;
  overflow: hidden;
  padding: 0 12px;
}

@media only screen and (max-width: 767px) {
  .loading {
    font-size: clamp(28px, 8vw, 42px);
    padding: 0 8px;
  }
}

.loading:before {
  display: block;
  color: rgba(255, 255, 255, 0.14);
  content: attr(data-loading-text);
}

.loading:after {
  display: block;
  top: 0;
  left: 0;
  width: 0;
  opacity: 1;
  color: var(--rr-color-common-white);
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  content: attr(data-loading-text);
  animation: loading 2.8s ease-in-out infinite;
}

@keyframes loading {
  0% {
    width: 0;
  }

  45% {
    width: 100%;
  }

  55% {
    width: 100%;
  }

  100% {
    width: 0;
  }
}

/*  Custom Cursor */
@media (min-width: 992px) {
  .mt-cursor {
    display: block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    position: fixed;
    left: 10px;
    top: 10px;
    user-select: none;
    pointer-events: none;
    visibility: hidden;
    z-index: 10000;
    -webkit-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);
    transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);
  }

  .mt-cursor:before {
    background: var(--rr-color-theme-primary);
    opacity: 1;
    content: "";
    width: 100%;
    height: 100%;
    border-radius: 50%;
    position: absolute;
    left: 0;
    top: 0;
    transition: all 0.3s ease;
  }

  .mt-cursor.cursor-grow:before {
    opacity: 0.7;
    transform: scale(1.5);
    transition: all 0.3s ease;
  }

  .mt-cursor.hide {
    opacity: 0;
    transition: opacity 0.3s ease;
    transition-delay: 0.4s;
  }

  .mt-cursor.hide .inner {
    transform: scale(0.1);
    transition: transform 0.3s ease;
  }
}

.sticky-widget {
  position: -webkit-sticky;
  position: sticky;
  top: 170px;
}

