/* cursor css */
/*! normalize.css v7.0.0 | MIT License | github.com/necolas/normalize.css */
.cb-cursor {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 150;
  contain: layout style size;
  pointer-events: none;
  will-change: transform;
  transition: opacity 0.3s, color 0.4s;
}

.cb-cursor:before {
  content: "";
  position: absolute;
  top: -24px;
  left: -24px;
  width: 48px;
  height: 48px;
  background: transparent;
  border-radius: 500px;
  transform: scale(0);
  transition: opacity 0.1s, transform 0.3s ease-in-out;
}

.cb-cursor-text {
  position: absolute;
  top: -18px;
  left: -18px;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  line-height: 20px;
  text-align: center;
  letter-spacing: -0.01em;
  opacity: 0;
  transform: scale(0) rotate(10deg);
  transition: opacity 0.4s, transform 0.3s;
  color: black;
}

/* Exclusion and Blending Modes */
@supports (mix-blend-mode: exclusion) {

  .cb-cursor.-exclusion,
  .cb-cursor.-opaque {
    mix-blend-mode: exclusion;
  }

  .cb-cursor.-exclusion:before,
  .cb-cursor.-opaque:before {
    background: white;
  }
}

.cb-cursor.-normal,
.cb-cursor.-text {
  mix-blend-mode: normal;
}

.cb-cursor.-normal:before,
.cb-cursor.-text:before {
  background: currentColor;
}

.cb-cursor.-inverse {
  color: white;
}

/* Cursor Visibility and Transformations */
.cb-cursor.-visible:before {
  transform: scale(0.2);
}

.cb-cursor.-visible.-active:before {
  transform: scale(0.23);
  transition-duration: 0.2s;
}

.cb-cursor.-pointer:before {
  transform: scale(0);
}

.cb-cursor.-text .cb-cursor-text {
  opacity: 1;
  transform: scale(1);
}

.cb-cursor.-text.-active:before {
  transform: scale(1.6);
  transition-duration: 0.2s;
}

.cb-cursor.all-element:before {
  transform: scale(1.6);
  opacity: 0.2;
  transition-duration: 0.2s;
}

.cb-cursor.-opaque:before {
  transform: scale(1.32);
}

.cb-cursor.-text:before {
  background: #fff;
  opacity: 1;
  backdrop-filter: blur(10px);
  transform: scale(3);
}

.cb-cursor.-opaque.-active:before {
  transform: scale(1.2);
}

.cb-cursor.-lg:before {
  transform: scale(2);
}

.cb-cursor.-hidden:before {
  transform: scale(0);
}

.cb-cursor.-text-blue:before {
  background: #3F5AF3;
}

.cb-cursor.-text-blue .cb-cursor-text {
  color: white;
}

