/* ===== Graphics Solutions — free quote form ===== */
.gc-free-quote-section {
  background-color: #0D1F2D;
}

.gc-free-quote-heading {
  max-width: 780px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 50px;
}

.gc-free-quote-heading .sub-heading {
  color: var(--rr-color-theme-primary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.gc-free-quote-title {
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: clamp(28px, 3vw, 42px);
  margin-bottom: 16px;
  color: var(--rr-color-common-white);
}

.gc-free-quote-desc {
  max-width: 680px;
  margin: 0 auto;
  color: rgba(255, 255, 255, 0.78);
  font-size: 16px;
  line-height: 1.75;
}

.gc-free-quote-card {
  background: var(--rr-color-common-white);
  border-radius: 20px;
  padding: clamp(28px, 4vw, 48px);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.22);
}

.gc-free-quote-form .form-item {
  margin-bottom: 0;
}

.gc-free-quote-form .form-item>label {
  display: block;
  margin-bottom: 10px;
  color: var(--rr-color-heading-primary);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.4;
}

.gc-free-quote-form label .required {
  color: var(--rr-color-text-body-light);
  font-weight: 600;
}

.gc-free-quote-form .form-control {
  width: 100%;
  min-height: 50px;
  padding: 12px 16px;
  border-radius: 8px;
  border: 1px solid var(--rr-color-border-light);
  background-color: var(--rr-color-common-white);
  color: var(--rr-color-heading-primary);
  font-size: 15px;
  line-height: 1.4;
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}

.gc-free-quote-form .form-control:focus {
  outline: none;
  border-color: var(--rr-color-theme-primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rr-color-theme-primary) 18%, transparent);
}

.gc-free-quote-form .form-control::placeholder {
  color: #aab0b6;
}

.gc-free-quote-form .gc-quote-textarea {
  min-height: 140px;
  resize: vertical;
}

.gc-free-quote-options-row {
  margin-top: 8px;
}

.gc-free-quote-form label .gc-upload-limit {
  color: var(--rr-color-text-body-light);
  font-weight: 600;
}

.gc-upload-zone {
  position: relative;
  min-height: 220px;
  border: 2px dashed var(--rr-color-border-light);
  border-radius: 12px;
  background: var(--rr-color-grey-1);
  cursor: pointer;
  transition: border-color 0.25s ease, background-color 0.25s ease, box-shadow 0.25s ease;
}

.gc-upload-zone:hover,
.gc-upload-zone.is-dragover,
.gc-upload-zone:focus-visible {
  border-color: var(--rr-color-theme-primary);
  background: color-mix(in srgb, var(--rr-color-theme-primary) 6%, var(--rr-color-grey-1));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rr-color-theme-primary) 12%, transparent);
  outline: none;
}

.gc-upload-input {
  position: absolute;
  width: 0;
  height: 0;
  opacity: 0;
  pointer-events: none;
}

.gc-upload-zone-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 220px;
  padding: 24px 20px;
  text-align: center;
}

.gc-upload-zone.has-files .gc-upload-zone-inner {
  min-height: 120px;
  padding-bottom: 12px;
}

.gc-upload-icon {
  font-size: 34px;
  color: var(--rr-color-theme-primary);
  margin-bottom: 12px;
}

.gc-upload-title {
  margin: 0 0 6px;
  color: var(--rr-color-heading-primary);
  font-size: 16px;
  font-weight: 700;
}

.gc-upload-or {
  margin: 0 0 10px;
  color: var(--rr-color-text-body-light);
  font-size: 14px;
}

.gc-upload-browse {
  border: none;
  background: none;
  padding: 0;
  color: var(--rr-color-theme-primary);
  font-size: 15px;
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.gc-upload-browse:hover {
  color: color-mix(in srgb, var(--rr-color-theme-primary) 80%, #000);
}

.gc-upload-file-list {
  list-style: none;
  margin: 0;
  padding: 0 16px 16px;
  width: 100%;
}

.gc-upload-file-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  margin-top: 8px;
  border-radius: 8px;
  background: var(--rr-color-common-white);
  border: 1px solid var(--rr-color-border-light);
}

.gc-upload-file-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--rr-color-heading-primary);
  font-size: 14px;
  font-weight: 600;
}

.gc-upload-file-size {
  color: var(--rr-color-text-body-light);
  font-size: 13px;
  white-space: nowrap;
}

.gc-upload-file-remove {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border: none;
  border-radius: 6px;
  background: rgba(17, 21, 28, 0.06);
  color: var(--rr-color-heading-primary);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.gc-upload-file-remove:hover {
  background: var(--rr-color-theme-primary);
  color: var(--rr-color-common-white);
}

.gc-check-list {
  list-style: none;
  margin: 0;
  padding: 14px 16px;
  border: 1px solid var(--rr-color-border-light);
  border-radius: 12px;
  background: var(--rr-color-grey-1);
  max-height: 220px;
  overflow-y: auto;
}

.gc-check-list li+li {
  margin-top: 10px;
}

.gc-check-item {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  cursor: pointer;
  user-select: none;
  position: relative;
  width: 100%;
}

.gc-check-item input {
  position: absolute;
  left: 0;
  top: 50%;
  width: 18px;
  height: 18px;
  margin: 0;
  opacity: 0;
  transform: translateY(-50%);
  cursor: pointer;
  z-index: 2;
}

.gc-check-box {
  display: inline-block;
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  box-sizing: border-box;
  border-radius: 4px;
  border: 2px solid var(--rr-color-border-light);
  background: var(--rr-color-common-white);
  position: relative;
  transition: border-color 0.2s ease, background-color 0.2s ease;
}

.gc-check-item--radio .gc-check-box {
  border-radius: 50%;
}

.gc-check-box::after {
  content: "";
  position: absolute;
  left: 4px;
  top: 1px;
  width: 5px;
  height: 9px;
  border: solid var(--rr-color-common-white);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg) scale(0);
  transition: transform 0.15s ease;
}

.gc-check-item--radio .gc-check-box::after {
  left: 50%;
  top: 50%;
  width: 8px;
  height: 8px;
  border: none;
  border-radius: 50%;
  background: var(--rr-color-common-white);
  transform: translate(-50%, -50%) scale(0);
}

.gc-check-item input:checked+.gc-check-box {
  background: var(--rr-color-theme-primary);
  border-color: var(--rr-color-theme-primary);
}

.gc-check-item input:checked+.gc-check-box::after {
  transform: rotate(45deg) scale(1);
}

.gc-check-item--radio input:checked+.gc-check-box::after {
  transform: translate(-50%, -50%) scale(1);
}

.gc-check-item input:focus-visible+.gc-check-box {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rr-color-theme-primary) 22%, transparent);
}

.gc-check-label {
  color: var(--rr-color-heading-primary);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.35;
}

.gc-free-quote-form .form-item--instructions {
  margin-top: 8px;
}

.gc-free-quote-submit {
  width: 100%;
  justify-content: center;
  margin-top: 28px;
  padding: 20px 30px;
  border-radius: 8px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
}

.gc-free-quote-submit:disabled {
  opacity: 0.72;
  cursor: not-allowed;
}

