/* ===== Index — fixed left side quick nav ===== */
.gc-fixed-side-nav {
  position: fixed;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  z-index: 998;
  pointer-events: none;
}

.gc-fixed-side-nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.gc-fixed-side-nav-list li {
  width: 56px;
  overflow: hidden;
  transition: width 0.38s cubic-bezier(0.4, 0, 0.2, 1);
}

.gc-fixed-side-nav-list li:hover,
.gc-fixed-side-nav-list li:focus-within {
  width: 260px;
  z-index: 3;
}

.gc-fixed-side-nav-item {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 56px;
  text-decoration: none;
  color: var(--rr-color-common-white);
  pointer-events: auto;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.18);
  transition: box-shadow 0.3s ease, filter 0.3s ease;
}

.gc-fixed-side-nav-list li.is-active {
  z-index: 2;
}

.gc-fixed-side-nav-item.is-active::after {
  content: "";
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  border-radius: 2px 0 0 2px;
  background: rgba(255, 255, 255, 0.95);
  box-shadow: -2px 0 8px rgba(255, 255, 255, 0.35);
  z-index: 2;
}

.gc-fixed-side-nav-list li:hover .gc-fixed-side-nav-item,
.gc-fixed-side-nav-list li:focus-within .gc-fixed-side-nav-item {
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.28);
}

.gc-fixed-side-nav-icon {
  width: 56px;
  min-width: 56px;
  height: 56px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.02em;
  flex-shrink: 0;
  color: var(--rr-color-common-white);
}

.gc-fixed-side-nav-label {
  flex: 1;
  min-width: 0;
  display: block;
  opacity: 0;
  visibility: hidden;
  white-space: nowrap;
  padding: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--rr-color-common-white);
  transition: opacity 0.28s ease, visibility 0.28s ease, padding 0.38s cubic-bezier(0.4, 0, 0.2, 1);
}

.gc-fixed-side-nav-list li:hover .gc-fixed-side-nav-label,
.gc-fixed-side-nav-list li:focus-within .gc-fixed-side-nav-label {
  opacity: 1;
  visibility: visible;
  padding: 0 20px 0 4px;
}

.gc-fixed-side-nav-item--1 {
  background-color: var(--rr-color-theme-primary);
}

.gc-fixed-side-nav-item--2 {
  background-color: #3b82c4;
}

.gc-fixed-side-nav-item--3 {
  background-color: #1e4a72;
}

.gc-fixed-side-nav-item--4 {
  background-color: #3d4f5f;
}

.gc-fixed-side-nav-list li:first-child .gc-fixed-side-nav-item {
  border-radius: 0 8px 0 0;
}

.gc-fixed-side-nav-list li:last-child .gc-fixed-side-nav-item {
  border-radius: 0 0 8px 0;
}

/* Light theme */
[data-theme=light] .gc-fixed-side-nav-item {
  box-shadow: 0 8px 22px rgba(17, 21, 28, 0.14);
}

[data-theme=light] .gc-fixed-side-nav-item.is-active::after {
  background: #ffc226;
  box-shadow: -2px 0 10px rgba(255, 194, 38, 0.45);
}

[data-theme=light] .gc-fixed-side-nav-list li:hover .gc-fixed-side-nav-item,
[data-theme=light] .gc-fixed-side-nav-list li:focus-within .gc-fixed-side-nav-item {
  box-shadow: 0 12px 30px rgba(17, 21, 28, 0.2);
}

[data-theme=light] .gc-fixed-side-nav-item--1 {
